import{_ as o,o as r,c as e,a5 as d}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"实现的不同","description":"底层实现上， CommonJS 和 ESModule (ESM) 的主要区别在于 模块解析、加载、缓存和执行的机制 不同。下面我们深入讲讲这两者的底层实现区别： 1. 加载机制 CommonJS：运行时加载 require 是一个函数 ，在代码运行时被调用。 加载模块时，Node。","frontmatter":{"title":"实现的不同","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"底层实现上， CommonJS 和 ESModule (ESM) 的主要区别在于 模块解析、加载、缓存和执行的机制 不同。下面我们深入讲讲这两者的底层实现区别： 1. 加载机制 CommonJS：运行时加载 require 是一个函数 ，在代码运行时被调用。 加载模块时，Node。","sidebarWeight":3,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/CommonJS 和 ESModule（ESM）/实现的不同.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/实现的不同.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/实现的不同.md"}'),n={name:"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/实现的不同.md"};function s(l,t,a,i,g,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<div><h1 id="实现的不同" tabindex="-1">实现的不同 <a class="header-anchor" href="#实现的不同" aria-label="Permalink to &quot;实现的不同&quot;">​</a></h1><blockquote><p>本节目标：理解“实现的不同”的核心思路，并能把它用于实际开发或面试表达。 底层实现上，<strong>CommonJS</strong> 和 <strong>ESModule (ESM)</strong> 的主要区别在于<strong>模块解析、加载、缓存和执行的机制</strong>不同。下面我们深入讲讲这两者的底层实现区别：</p></blockquote><p><strong>1. 加载机制</strong><strong>CommonJS：运行时加载</strong></p><ul><li><strong>require 是一个函数</strong>，在代码运行时被调用。</li><li>加载模块时，Node 会<strong>同步读取文件内容</strong>，<strong>包装成函数执行</strong>（见下文）。</li><li>缓存的是模块的 exports 对象。</li></ul><p><strong>底层流程：</strong> // require(&#39;foo&#39;) 背后的流程1. 解析模块路径2. 读取文件内容3. 包裹一层函数：(function(exports, require, module, __filename, __dirname) { ... })4. 执行这个函数，并传入 require 等参数5. 返回 module.exports</p><p><strong>ESModule：编译时加载（静态）</strong></p><ul><li>import 是<strong>静态语法</strong>，在模块解析阶段就会确定依赖关系。</li><li>加载是异步的，<strong>先分析依赖图，再执行代码</strong>。</li><li>ESModule <strong>支持循环引用的实时绑定（live bindings）</strong>。</li></ul><p><strong>底层流程：</strong></p><ol><li>解析模块路径（支持 import map）2. 预扫描所有 import/export（构建依赖图）3. 确定模块之间依赖顺序4. 初始化模块（但不执行代码）5. 按依赖顺序执行模块</li></ol><p><strong>2. 包装机制</strong><strong>CommonJS</strong></p><ul><li>Node 会将每个模块包裹成如下函数：(function (exports, require, module, __filename, __dirname) { // 模块源码});</li><li>相当于每个文件是一个闭包，形成模块作用域。</li></ul><p><strong>ESModule</strong></p><ul><li>不需要函数包裹，天然具有模块作用域。</li><li>通过 V8 的<strong>Module Record</strong> 实现，每个模块是一个记录，存储导入导出等信息。</li></ul><p><strong>3. 缓存机制</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>CommonJS</strong></td><td><strong>ESModule</strong></td></tr><tr><td>缓存位置</td><td>require.cache</td><td>内部模块记录表</td></tr><tr><td>缓存对象</td><td>module.exports</td><td>Module Namespace Object</td></tr><tr><td>执行时机</td><td>首次 require 就立即执行</td><td>所有依赖扫描完后，再按顺序执行</td></tr></tbody></table><p><strong>4. 导出方式</strong><strong>CommonJS</strong></p><ul><li>值拷贝（不是 live binding）：exports.a = 1;setTimeout(() =&gt; exports.a = 2, 1000);另一个模块 require 后，拿到的是 { a: 1 }，不会变。</li></ul><p><strong>ESM</strong></p><ul><li>实时绑定（live binding）：export let a = 1;setTimeout(() =&gt; a = 2, 1000);import 这模块的另一个模块访问 a 会实时拿到最新值。</li></ul><p><strong>总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>项目</strong></td><td><strong>CommonJS</strong></td><td><strong>ESModule</strong></td></tr><tr><td>加载时机</td><td>运行时加载</td><td>编译阶段静态分析</td></tr><tr><td>执行机制</td><td>同步，立即执行</td><td>异步，按依赖图顺序执行</td></tr><tr><td>包装方式</td><td>包裹成函数（Function Wrapper）</td><td>原生模块作用域（Module Record）</td></tr><tr><td>导出机制</td><td>值拷贝</td><td>实时绑定（Live Binding）</td></tr><tr><td>缓存</td><td>require.cache，缓存 exports</td><td>模块记录，缓存 namespace 对象</td></tr><tr><td>支持循环引用</td><td>支持但值固定</td><td>支持并保证导出实时更新</td></tr></tbody></table><p>如果你在研究 Node.js 内部实现或准备构建模块打包器（如 Webpack 插件），这些区别尤为重要。如果你想深入某一块（比如 module cache、循环引用处理、V8 的 Module 实现等），我可以继续扩展。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const c=o(n,[["render",s]]);export{m as __pageData,c as default};
